create table tb_address (property_id int4 not null, number int4, street varchar(255), city_id int4, primary key (property_id));
create table tb_city (id int4 generated by default as identity, name varchar(255), county_id int4, primary key (id));
create table tb_county (id int4 generated by default as identity, name varchar(255), state_id int4, primary key (id));
create table tb_property (id int4 generated by default as identity, baths int4, beds int4, built int4, image varchar(255), price float8, title varchar(255), primary key (id));
create table tb_state (id int4 generated by default as identity, name varchar(255), primary key (id));
alter table if exists tb_address add constraint FKpm4x3qy2wea2p4ea7bs217nr5 foreign key (city_id) references tb_city;
alter table if exists tb_address add constraint FKudkbb7774emcf4bp06la6bxx foreign key (property_id) references tb_property;
alter table if exists tb_city add constraint FKm95g6tnrtkca8ytexdog939uw foreign key (county_id) references tb_county;
alter table if exists tb_county add constraint FKg5dhq7q1ac4qhhepmci2o0mf5 foreign key (state_id) references tb_state;
